import {HILL_CROPS,HILL_ITEMS,HILL_NOTES,HILL_ORDERS,HILL_RECIPES,DIRECTIONS,MIRROR_TARGET,hillObjective,hillCookReason,hillOrderNeed} from './hill.js?v=0.13.3';
import {ROOMS,sceneOf} from './indoors.js?v=0.13.3';
import {itemArt} from './item-art.js?v=0.13.3';
export function createHillUI({getState,world,run,openModal,closeModal,button,showJournal,mark,canPay,ITEMS}){
 const s=getState,h=()=>s().hill,actions=x=>`<div class="action-list">${x}</div>`,panel=(title,body,kind='hill')=>openModal(kind,'',title,body);
 const doIt=(label,type,payload,again,disabled='',small='')=>button(label,()=>{if(run(type,payload))again();},{primary:true,disabled,small});
 const follow=()=>button('标记山坡的下一步',()=>{mark();closeModal();});
 const back=()=>button('继续走走',closeModal);
 const askRepair=(key,label,type,r)=>doIt(label,type,{},()=>repair(key),canPay(s(),r),`体力${r.energy} · ${r.minutes}分钟`);
 function board(){panel('夜市之后的来信',()=>{
  const q=hillObjective(s());return `<p class="quote">“从前，山坡温室每晚亮灯，晚归的人就知道山路尽头还有人。我们能不能把它重新打开？”</p><p>${q.body}</p>${actions(!h().started?doIt('收好来信，沿北路上山','hillStart',{},()=>{mark();board();}):h().food&&!h().invited?doIt('留下山坡点灯的邀请','hillInvite',{},board):h().invited&&!h().lit?'<p>✓ 邀请已留下 · 任意晚间18:00后，在温室点灯。</p>':'')}${h().lit?ordersHTML():''}${actions(follow()+button('翻开山坡手记',()=>showJournal('hill'))+back())}`;
 });}
 function note(i){const n=HILL_NOTES[i];panel(n.name,()=>`<p class="quote">${n.text}</p><p>三页笔记固定留在风铃树、观景台与旧石牌；可以按任意顺序寻找。</p>${actions(doIt(h().notes[i]?'这页已记下':'把这页收进手记','hillNote',{id:n.id},()=>note(i),h().notes[i]?'可以在手记里重读':'')+follow()+back())}`);}
 function recipeHTML(again=bench){return !h().light?'':`<div class="home-recipes hill-recipes">${Object.entries(HILL_RECIPES).map(([key,r])=>`<section>${itemArt(key)}<h3>${r.name}</h3><p>${Object.entries(r.need).map(([k,n])=>`${ITEMS[k].name} ${s().inventory[k]+(sceneOf(s())==='home'?(s().life.chest[k]||0):0)}/${n}`).join(' · ')}</p>${actions(doIt('制作'+r.name,'hillCook',{recipe:key},again,hillCookReason(s(),key),`体力${r.energy} · ${r.minutes}分钟 · 售${HILL_ITEMS[key].sell}金币`))}</section>`).join('')}</div>`;}
 function notesHTML(){return `<div class="hill-notes">${HILL_NOTES.map((n,i)=>`<section><h3>${h().notes[i]?'✓ ':''}${n.name}</h3><p>${h().notes[i]?n.text:'尚未找到，沿山路走近这个地标。'}</p></section>`).join('')}</div>`;}
 function bench(){panel('公共育苗屋 · 工作台',()=>{
  const ready=h().notes.every(Boolean);return `<p>${h().light?'种子放在左手边，右边留给大家做汤和泡茶。第一次接通光路赠送的种子，每种2包。':'旧笔记把光、水和幼苗写在一起。先看懂它们，再把这里重新收拾好。'}</p>${!h().planned?notesHTML()+`<div class="town-letter-grid">${[['left','左床 · 长日照'],['right','右床 · 午后遮阴']].map(([id,label])=>`<label>${label}<select id="hill-${id}"><option value="">选择作物</option><option value="tomato">番茄</option><option value="mint">薄荷</option></select></label>`).join('')}</div>${actions(button('按笔记安排育苗床',()=>{if(run('hillPlan',{left:document.querySelector('#hill-left').value,right:document.querySelector('#hill-right').value}))bench();},{primary:true,disabled:ready?'':'先找齐三页笔记',small:'选错可以重新安排，不扣材料'}))}`:!h().light?`<p>✓ 左床番茄，右床薄荷。${hillObjective(s()).body}</p>`:''}${h().light?`<div class="hill-seeds">${Object.entries(HILL_CROPS).map(([key,c])=>`<section>${itemArt(c.seed)}<h3>${c.name}种子</h3><p>随身 ${s().inventory[c.seed]} 包 · 每包 ${c.price} 金币</p>${actions(doIt('补一包'+c.name+'种子','hillSeeds',{crop:key},bench,s().coins<c.price?'金币不足':''))}${!h().harvested[key]&&!h().beds[key==='mint'?1:0].crop&&s().inventory[c.seed]+(s().life.chest[c.seed]||0)===0&&s().coins<c.price?actions(doIt('领取首收前的补种','hillRelief',{crop:key},bench)):''}</section>`).join('')}</div>${recipeHTML()}<p class="small-note">本工作台使用随身食材。面粉在庄园磨坊加工；干香草在雾松林晾制。</p>${actions(h().food?'<p>✓ 汤与茶已经留好，不会腐坏。</p>':doIt('留下一份浓汤和薄荷茶','hillPrepare',{},bench,!h().harvested.tomato||!h().harvested.mint?'先采收两种作物':canPay(s(),{need:{tomatoSoup:1,mintTea:1}}),'留好后去广场告示板邀请街坊'))}`:''}${actions(follow()+back())}`;
 });}
 function repair(key){const vines=key==='vines',done=vines?h().cleared:h().water,r=vines?{energy:5,minutes:15}:{need:{wood:4,stone:2,resin:1},energy:6,minutes:20};panel(vines?'让日光进来':'接通集雨槽',()=>`<p>${vines?'把压住玻璃的枯藤剪开，留下仍在开花的绿枝。':'水槽收集屋顶雨水；接好铜管后，雨天会自动照料两床幼苗。'}</p>${r.need?`<p>${Object.entries(r.need).map(([k,n])=>`${ITEMS[k].name} ${s().inventory[k]}/${n}`).join(' · ')}</p>`:''}${actions(done?'<p>✓ 已经修好。</p>':!h().planned?'<p>先在工作台按三页笔记安排种植位置。</p>':askRepair(key,vines?'理好窗前枯藤':'接通铜管与集雨槽',vines?'hillClear':'hillWater',r))}${actions(follow()+back())}`);}
 function lightPath(){let count=0;while(count<3&&h().mirrors[count]===MIRROR_TARGET[count])count++;return `<div class="light-path" role="img" aria-label="光路已连通${count}面，共三面"><span>日光</span>${h().mirrors.map((d,i)=>`<span class="${i<count?'lit':''}">→ ${i+1} · ${DIRECTIONS[d]} ${i<count?'✓':'○'}</span>`).join('')}<span>${count===3?'→ 幼苗 ✓':'未到达幼苗'}</span></div>`;}
 function mirror(i){panel('第'+(i+1)+'面反光板',()=>`<p>铜圈刻着四个方向。顺时针转动，每次一格，不消耗体力或材料。</p>${lightPath()}<p class="quote">石牌笔记：从左到右，东 → 南 → 东。</p><p class="small-note">这是白天的采光路线；雨天和夜间也可以按刻度校准。右边最后一只铜圈是集雨水位表，不参与光路。</p>${actions(doIt('顺时针转动第'+(i+1)+'面','hillRotate',{index:i},()=>mirror(i),h().light?'支架已经固定':!h().water||!h().cleared?'先清藤、接通供水':''))}${i===1?actions(doIt('固定支架，让光照到幼苗','hillFocus',{},()=>mirror(i),h().light?'已经接通':!h().cleared||!h().water?'先修复光照和供水':!h().mirrors.every((d,j)=>d===MIRROR_TARGET[j])?'按笔记连通三面反光板':'')):actions(button(i===2?'回中间固定支架':'下一面反光板',()=>{closeModal();world.go(ROOMS.greenhouse.spots.find(p=>p.id==='greenMirror'+1));}))}${h().light?'<p>✓ 首批种子与食谱已经放入背包、记入手记。</p>':''}${actions(follow()+back())}`);}
 function bed(i){const key=i?'mint':'tomato',c=HILL_CROPS[key];panel((i?'右床':'左床')+' · '+c.name,()=>{const b=h().beds[i],wet=b.tended||s().weather==='rain';return `${itemArt(key)}<p>${!h().light?'先让温室的光路与水槽恢复。':!b.crop?`这床留给${c.name}。随身种子 ${s().inventory[c.seed]} 包；每次1包，固定收获${c.yield}份。`:b.growth===2?`已经成熟。${c.name}会等你，不会腐坏。`:`有照料的夜晚 ${b.growth}/2 · ${wet?s().weather==='rain'?'屋顶集雨槽已补水':'今天已经浇水':'今天还需要浇水'}`}</p>${actions(!b.crop?doIt('播种'+c.name,'hillPlant',{index:i},()=>bed(i),!h().light?'先修复温室':canPay(s(),{need:{[c.seed]:1},energy:2}),'体力2 · 5分钟'):b.growth===2?doIt('采收'+c.name+' ×'+c.yield,'hillHarvest',{index:i},()=>bed(i),s().energy<2?'体力不足':'','体力2 · 5分钟'):doIt('照料这一床幼苗','hillTend',{index:i},()=>bed(i),wet?'今日已照料':s().energy<2?'体力不足':'','体力2 · 5分钟'))}<p class="small-note">浇水后回家睡觉才会生长；雨天自动照料。等到傍晚、换地图或重新打开游戏都不会催熟。</p>${actions(button('去工作台看种子与食谱',()=>{closeModal();world.go(ROOMS.greenhouse.spots.find(p=>p.id==='greenBench'));}))+actions(follow()+back())}`;});}
 function lamp(){panel('山坡上的灯',()=>`<p>${h().lit?'这盏灯会继续照亮幼苗和回家的路。你可以再来坐一会儿。':h().invited?'街坊已经收到邀请。不用挑一个晴天，18:00以后，在这里把灯点起来。':'等第一批收成变成汤和茶，再邀请街坊来看看。'}</p>${actions(h().lit?button('重读点灯那晚',()=>finale(0),{primary:true}):doIt('点亮山坡的铜灯','hillLight',{},()=>{mark();finale(0);},!h().invited?'先备好汤茶并留下邀请':s().minute<1080?'18:00后再来':''))}${actions(s().minute<1080?button('在窗边等到18:00',()=>{if(run('wait'))lamp();}):'')}${actions(follow()+back())}`);}
 function finale(i){world.hillGathering=true;const parts=[['玻璃上的第一点暖光',s().water.started&&!s().water.reported?'露西读完陶恩和米菈留下的便笺，在桌边给他们留了位置。温室的故事不用等调查结束，两人的椅子也不会被收走。':'陶恩放下工具，米菈把最后一角桌布抚平。露西说，今晚谁也不用站着把饭吃完。'],['有人留下，有人远行',(s().flags.departed?'远处的传承磨轮还在转。露西把汤放在灯边：“爷爷，这次不加糖。”':'奥伦的字条压在种子袋下：“番茄不是南瓜，别什么都拿去烤派。”露西把它认真收好。')+(s().expansion.flags.veraDeparted?'薇拉的铜燕子被画进纪念画，山路也成了回信的一部分。':'薇拉让露西捎来一句话：下次路过，她会记得把送信人的那杯茶喝掉。')],['山路尽头，有人在等',s().water.reported?'旧水渠的报告已经封存，今晚大家聊的是下一床种什么。温室的灯亮了，生活还会接着长。':'暂时不用讨论远处的异样。今晚先把小苗照料好，给后来的人留下光。']];panel(parts[i][0],()=>`<p class="quote">${parts[i][1]}</p><p class="small-note">${i+1}/3 · ${i===2?'第二部本章完成。温室可重复种植，广场开放三类订单，家中可挂铜灯与纪念画。':'灯下的一会儿'}</p>${actions(button(i<2?'听听下一段':'回到育苗屋，继续生活',()=>i<2?finale(i+1):closeModal(),{primary:true}))}`,'townTalk');}
 function ordersHTML(){const o=h().order,r=HILL_ORDERS[o.kind];if(r)return `<section class="hill-order"><h3>已接 · ${r.name}</h3><p>${o.kind==='fish'?'银尾小鱼或河鲫，共2条':Object.entries(r.need).map(([k,n])=>`${ITEMS[k].name} ${s().inventory[k]}/${n}`).join(' · ')} · 奖励${r.coins}金币</p><p>不限日期，跨天仍保留；每天共交付一单。</p>${actions(doIt('交付这份委托','hillOrderDeliver',{},board,o.day===s().day?'今天已经交付':canPay(s(),{need:hillOrderNeed(s())}))+doIt('暂时放回委托','hillOrderCancel',{},board))}</section>`;
  return `<h3>街坊的新委托</h3><p>种植、料理、钓鱼任选一单；每天共交付一单，接取后没有期限。</p>${actions(Object.entries(HILL_ORDERS).map(([kind,r])=>doIt('接取 · '+r.name,'hillOrderAccept',{kind},board,o.day===s().day?'今天已完成，明天再来':'',`${kind==='fish'?'普通鱼2条':Object.entries(r.need).map(([k,n])=>ITEMS[k].name+n).join('、')} · ${r.coins}金币`)).join(''))}`;
 }
 function decor(){panel('留在家里的风景',()=>`<p>这些纪念挂在墙上，走动的地方还是空着。</p><div class="keepsake-list"><p>丰收节的麦穗、河岸笔记和邮差的铜燕子，都有各自的位置。</p></div>${actions(doIt(h().decor.lamp?'收起山坡铜灯':'挂上山坡铜灯','hillDecor',{key:'lamp'},decor)+doIt(h().decor.painting?'收起山坡纪念画':'挂上山坡纪念画','hillDecor',{key:'painting'},decor))}${s().neighborhood.mila===3?`<h3>米菈缝的窗帘</h3>${actions([['old','挂上米白绿枝窗帘'],['blue','挂上雨后蓝窗帘'],[null,'暂时收起窗帘']].map(([choice,label])=>doIt(label,'curtains',{choice},decor)).join(''))}`:''}${actions(button('翻开旅途记录',()=>showJournal('notes'))+back())}`);}
 function journalHTML(){const q=hillObjective(s());return `<div class="current-wish"><h3>${q.title}</h3><p>${q.body}</p><ul>${q.checks.map(([text,done])=>`<li class="${done?'done':''}">${done?'✓':'□'} ${text}</li>`).join('')}</ul></div>${actions(follow())}${h().started?notesHTML():''}${h().light?`<h3>育苗记录</h3><div class="hill-seeds">${h().beds.map((b,i)=>`<section><h3>${i?'右床 · 薄荷':'左床 · 番茄'}</h3><p>${!b.crop?'待播种':b.growth===2?'成熟，可收获':`成长${b.growth}/2夜 · ${b.tended||s().weather==='rain'?'今日已照料':'待浇水'}`}</p></section>`).join('')}</div><p>温室工作台补种、制作；雨天由集雨槽照料。地图路线：广场 → 旧果园北阶 → 风铃山坡 → 温室。</p>`:''}${h().lit?`<p>✓ 已获得60金币、铜灯与纪念画。家中纪念架可布置；广场可接新订单。</p>`:''}`;}
 function handle(t){if(t.id==='greenDoor'){panel('山坡温室',()=>`<p>玻璃蒙着薄薄的灰。窗边的土床空着，铜灯一直留在那里。</p>${actions(button('走进温室',()=>{if(run('enterRoom',{room:'greenhouse'}))closeModal();},{primary:true})+back())}`);return true;}
  const ni=HILL_NOTES.findIndex(p=>p.id===t.id);if(ni>=0){note(ni);return true;}if(t.id==='keepsake'&&h().lit){decor();return true;}
  if(t.id.startsWith('greenMirror')){mirror(Number(t.id.at(-1)));return true;}if(t.id.startsWith('greenBed')){bed(Number(t.id.at(-1)));return true;}
  const f={greenBench:bench,greenVines:()=>repair('vines'),greenWater:()=>repair('water'),greenLamp:lamp}[t.id];if(f){f();return true;}return false;
 }
 return {handle,board,journalHTML,recipeHTML,ordersHTML};
}
